from __future__ import annotations

import time
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Any
from urllib.parse import urlencode

from mage_agent.core.errors import ApiError
from mage_agent.core.http import MageApiClient

_TERMINAL_RUN_STATUSES = frozenset({"completed", "failed", "cancelled"})
_FAILED_BLOCK_STATUSES = frozenset({"failed", "cancelled"})


def _unwrap_entity(payload: Any, key: str) -> dict[str, Any]:
    if isinstance(payload, dict) and isinstance(payload.get(key), dict):
        return payload[key]
    if isinstance(payload, dict):
        return payload
    return {}


def _normalize_status(status: Any) -> str:
    return str(status or "").strip().lower()


def _is_terminal_run_status(status: Any) -> bool:
    return _normalize_status(status) in _TERMINAL_RUN_STATUSES


def _query_path(path: str, params: dict[str, Any]) -> str:
    filtered = {key: value for key, value in params.items() if value is not None}
    if not filtered:
        return path
    return f"{path}?{urlencode(filtered, doseq=True)}"


def _truncate_text(text: str, max_chars: int) -> str:
    if max_chars <= 0 or len(text) <= max_chars:
        return text
    return text[:max_chars] + "\n…(truncated)"


def _block_runs_from_pipeline_run(pipeline_run: dict[str, Any]) -> list[dict[str, Any]]:
    block_runs = pipeline_run.get("block_runs")
    if isinstance(block_runs, list):
        return [row for row in block_runs if isinstance(row, dict)]
    return []


def _coerce_pipeline_run_id(value: int | str, *, field: str = "pipeline_run_id") -> int:
    if isinstance(value, int):
        return value
    try:
        return int(value)
    except (TypeError, ValueError) as exc:
        raise ApiError(
            f"Invalid {field} '{value}': expected a numeric pipeline run ID."
        ) from exc


def _flatten_pipeline_log_entries(log_entries: list[Any]) -> list[dict[str, Any]]:
    flattened: list[dict[str, Any]] = []
    for entry in log_entries:
        if not isinstance(entry, dict):
            continue
        block_run_logs = entry.get("block_run_logs")
        if isinstance(block_run_logs, list):
            for block_log in block_run_logs:
                if isinstance(block_log, dict):
                    flattened.append(block_log)
            continue
        flattened.append(entry)
    return flattened


def _block_uuid_from_log_name(name: str | None) -> str | None:
    if not name:
        return None
    base = name.split(".", 1)[0]
    return base or None


def _execution_options_from_mapping(
    options: dict[str, Any] | None,
) -> dict[str, Any]:
    merged = options or {}
    kwargs: dict[str, Any] = {
        "variables": merged.get("variables"),
        "poll_interval_seconds": merged.get("poll_interval_seconds", 5),
        "timeout_seconds": merged.get("timeout_seconds", 1800),
        "schedule_payload": merged.get("schedule_payload"),
        "include_outputs": merged.get("include_outputs", True),
        "sample_count": merged.get("sample_count"),
        "include_log_content": merged.get("include_log_content", True),
        "max_log_chars": merged.get("max_log_chars", 8000),
    }
    return kwargs


@dataclass
class ExecutionTools:
    api: MageApiClient

    def run_pipeline(self, pipeline_uuid: str, payload: dict | None = None) -> Any:
        """Alias for execute_pipeline; accepts the same options via payload or kwargs."""
        return self.execute_pipeline(pipeline_uuid, **_execution_options_from_mapping(payload))

    def list_block_runs(self, pipeline_run_id: int | str) -> list[dict[str, Any]]:
        """List block runs for a pipeline run."""
        return self._list_block_runs(_coerce_pipeline_run_id(pipeline_run_id))

    def run_block(
        self,
        pipeline_uuid: str,
        block_uuid: str,
        *,
        variables: dict[str, Any] | None = None,
        record: bool = True,
        store_variables: bool = True,
        run_upstream_blocks: bool = False,
        incomplete_only: bool = False,
        payload: dict[str, Any] | None = None,
        timeout_seconds: int = 600,
    ) -> dict[str, Any]:
        """
        Execute a single block synchronously via the pipeline API trigger.

        Uses OAuth session auth to find or create an API schedule, then POST
        ``/api/runs`` with the schedule trigger token (not OAuth).
        """
        schedule = self._find_or_create_api_trigger(pipeline_uuid)
        token = schedule.get("token")
        if not token:
            raise ApiError("API trigger schedule does not include a token.")

        run_fields: dict[str, Any] = {
            "pipeline_uuid": pipeline_uuid,
            "block_uuid": block_uuid,
            "variables": variables or {},
            "record": record,
            "store_variables": store_variables,
            "run_upstream_blocks": run_upstream_blocks,
            "incomplete_only": incomplete_only,
        }
        if payload:
            nested_run = payload.get("run")
            if isinstance(nested_run, dict):
                run_fields.update(nested_run)
            else:
                run_fields.update(payload)

        response = self.api.post_with_trigger_token(
            "/api/runs",
            {"run": run_fields},
            str(token),
            timeout_seconds=timeout_seconds,
        )
        run_result = _unwrap_entity(response, "run")
        if not run_result and isinstance(response, dict):
            run_result = response

        return {
            "pipeline_uuid": pipeline_uuid,
            "block_uuid": block_uuid,
            "pipeline_schedule_id": schedule.get("id"),
            "pipeline_schedule_name": schedule.get("name"),
            "run": run_result,
        }

    def get_block_run_outputs(
        self,
        pipeline_run_id: int | str,
        *,
        sample_count: int = 100,
    ) -> dict[str, Any]:
        """Fetch block runs and per-block-run outputs for a pipeline run."""
        block_runs = self._list_block_runs(_coerce_pipeline_run_id(pipeline_run_id))
        block_outputs = self._collect_block_outputs(
            block_runs,
            sample_count=sample_count,
        )
        return {
            "pipeline_run_id": pipeline_run_id,
            "block_runs": block_runs,
            "block_outputs": block_outputs,
        }

    def get_logs(
        self,
        pipeline_uuid: str,
        run_id: int | str,
        *,
        include_log_content: bool = True,
        max_log_chars: int = 8000,
    ) -> dict[str, Any]:
        pipeline_run_id = _coerce_pipeline_run_id(run_id, field="run_id")
        logs = self._fetch_pipeline_run_logs(
            pipeline_uuid,
            pipeline_run_id=pipeline_run_id,
            include_log_content=include_log_content,
            max_log_chars=max_log_chars,
        )
        return {
            "pipeline_uuid": pipeline_uuid,
            "pipeline_run_id": run_id,
            **logs,
        }

    def execute_pipeline(
        self,
        pipeline_uuid: str,
        *,
        variables: dict[str, Any] | None = None,
        poll_interval_seconds: int = 5,
        timeout_seconds: int = 1800,
        schedule_payload: dict[str, Any] | None = None,
        include_outputs: bool = True,
        sample_count: int | None = None,
        include_log_content: bool = True,
        max_log_chars: int = 8000,
    ) -> dict[str, Any]:
        schedule = self._create_run_once_schedule(
            pipeline_uuid,
            variables=variables,
            schedule_payload=schedule_payload,
        )
        schedule_id = schedule.get("id")
        if schedule_id is None:
            raise ApiError("Pipeline schedule creation did not return an id.")

        pipeline_run = self._create_pipeline_run(
            int(schedule_id),
            schedule.get("token"),
            variables=variables,
        )
        run_id = pipeline_run.get("id")
        if run_id is None:
            raise ApiError("Pipeline run creation did not return an id.")

        pipeline_run, timed_out = self._poll_pipeline_run(
            int(run_id),
            poll_interval_seconds=poll_interval_seconds,
            timeout_seconds=timeout_seconds,
        )
        status = _normalize_status(pipeline_run.get("status"))

        block_runs = _block_runs_from_pipeline_run(pipeline_run)
        if not block_runs:
            block_runs = self._list_block_runs(int(run_id))
        failed_block_runs = [
            block_run
            for block_run in block_runs
            if _normalize_status(block_run.get("status")) in _FAILED_BLOCK_STATUSES
        ]

        block_outputs: dict[str, Any] = {}
        if include_outputs:
            block_outputs = self._collect_block_outputs(
                block_runs,
                sample_count=sample_count,
            )

        failure_logs = None
        if status in {"failed", "cancelled"} or failed_block_runs:
            failure_logs = self._fetch_failure_logs(
                pipeline_uuid,
                pipeline_run_id=int(run_id),
                include_log_content=include_log_content,
                max_log_chars=max_log_chars,
            )

        return {
            "pipeline_uuid": pipeline_uuid,
            "pipeline_schedule_id": schedule_id,
            "pipeline_run_id": run_id,
            "status": status,
            "timed_out": timed_out,
            "pipeline_run": pipeline_run,
            "block_runs": block_runs,
            "failed_block_runs": failed_block_runs,
            "block_outputs": block_outputs,
            "failure_logs": failure_logs,
        }

    def _list_pipeline_schedules(self, pipeline_uuid: str) -> list[dict[str, Any]]:
        try:
            response = self.api.get(
                _query_path(
                    "/api/pipeline_schedules",
                    {"pipeline_uuid": pipeline_uuid},
                ),
            )
            schedules = response.get("pipeline_schedules")
            if isinstance(schedules, list):
                return [row for row in schedules if isinstance(row, dict)]
        except ApiError:
            pass

        response = self.api.get(
            f"/api/pipelines/{pipeline_uuid}/pipeline_schedules",
        )
        schedules = response.get("pipeline_schedules")
        if isinstance(schedules, list):
            return [row for row in schedules if isinstance(row, dict)]
        return []

    def _find_or_create_api_trigger(self, pipeline_uuid: str) -> dict[str, Any]:
        schedules = self._list_pipeline_schedules(pipeline_uuid)
        api_schedules = [
            schedule
            for schedule in schedules
            if schedule.get("schedule_type") == "api" and schedule.get("token")
        ]
        for schedule in api_schedules:
            if _normalize_status(schedule.get("status")) == "active":
                return schedule
        if api_schedules:
            return api_schedules[0]

        schedule_fields: dict[str, Any] = {
            "name": f"api_trigger_{pipeline_uuid}",
            "schedule_type": "api",
            "status": "active",
        }
        create_paths = [
            (f"/api/pipelines/{pipeline_uuid}/pipeline_schedules", schedule_fields),
            (
                "/api/pipeline_schedules",
                {**schedule_fields, "pipeline_uuid": pipeline_uuid},
            ),
        ]
        last_error: ApiError | None = None
        for path, fields in create_paths:
            try:
                response = self.api.post(path, {"pipeline_schedule": fields})
                return _unwrap_entity(response, "pipeline_schedule")
            except ApiError as exc:
                last_error = exc
        if last_error:
            raise last_error
        raise ApiError("Unable to create API trigger schedule.")

    def _create_run_once_schedule(
        self,
        pipeline_uuid: str,
        *,
        variables: dict[str, Any] | None,
        schedule_payload: dict[str, Any] | None,
    ) -> dict[str, Any]:
        now = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
        schedule_fields: dict[str, Any] = {
            "name": f"mage-agent-once-{int(time.time())}",
            "schedule_type": "time",
            "schedule_interval": "@once",
            "status": "inactive",
            "start_time": now,
            "variables": variables or {},
            "settings": {
                "create_initial_pipeline_run": False,
            },
        }
        if schedule_payload:
            schedule_fields.update(schedule_payload)

        response = self.api.post(
            f"/api/pipelines/{pipeline_uuid}/pipeline_schedules",
            {"pipeline_schedule": schedule_fields},
        )
        return _unwrap_entity(response, "pipeline_schedule")

    def _create_pipeline_run(
        self,
        schedule_id: int,
        schedule_token: str | None,
        *,
        variables: dict[str, Any] | None,
    ) -> dict[str, Any]:
        run_variables = variables or {}
        nested_body = {"pipeline_run": {"variables": run_variables}}
        paths = [
            f"/api/pipeline_schedules/{schedule_id}/pipeline_runs",
        ]
        if schedule_token:
            paths.append(
                f"/api/pipeline_schedules/{schedule_id}/pipeline_runs/{schedule_token}"
            )

        last_error: ApiError | None = None
        for index, path in enumerate(paths):
            body: dict[str, Any] = nested_body if index == 0 else run_variables
            try:
                response = self.api.post(path, body)
                return _unwrap_entity(response, "pipeline_run")
            except ApiError as exc:
                last_error = exc
        if last_error:
            raise last_error
        raise ApiError("Unable to create pipeline run.")

    def _poll_pipeline_run(
        self,
        run_id: int,
        *,
        poll_interval_seconds: int,
        timeout_seconds: int,
    ) -> tuple[dict[str, Any], bool]:
        deadline = time.monotonic() + max(timeout_seconds, 0)
        latest = self._get_pipeline_run(run_id)

        while not _is_terminal_run_status(latest.get("status")):
            if time.monotonic() >= deadline:
                return latest, True
            time.sleep(max(poll_interval_seconds, 1))
            latest = self._get_pipeline_run(run_id)

        return latest, False

    def _get_pipeline_run(self, run_id: int) -> dict[str, Any]:
        response = self.api.get(f"/api/pipeline_runs/{run_id}")
        return _unwrap_entity(response, "pipeline_run")

    def _list_block_runs(self, pipeline_run_id: int) -> list[dict[str, Any]]:
        try:
            response = self.api.get(
                _query_path("/api/block_runs", {"pipeline_run_id": pipeline_run_id}),
            )
            block_runs = response.get("block_runs") if isinstance(response, dict) else None
            if isinstance(block_runs, list):
                rows = [row for row in block_runs if isinstance(row, dict)]
                if rows:
                    return rows
        except ApiError:
            pass

        pipeline_run = self._get_pipeline_run(pipeline_run_id)
        return _block_runs_from_pipeline_run(pipeline_run)

    def _get_block_run_outputs(
        self,
        block_run_id: int,
        *,
        sample_count: int,
    ) -> dict[str, Any]:
        path = _query_path(
            f"/api/block_runs/{block_run_id}/outputs",
            {"sample_count": sample_count},
        )
        response = self.api.get(path)
        if isinstance(response, dict):
            return {
                "outputs": response.get("outputs") or [],
                "metadata": response.get("metadata"),
            }
        return {"outputs": [], "metadata": None}

    def _collect_block_outputs(
        self,
        block_runs: list[dict[str, Any]],
        *,
        sample_count: int | None,
    ) -> dict[str, Any]:
        resolved_sample_count = sample_count if sample_count is not None else 100
        outputs: dict[str, Any] = {}
        for block_run in block_runs:
            block_run_id = block_run.get("id")
            block_uuid = block_run.get("block_uuid") or block_run.get("uuid")
            if block_run_id is None or not block_uuid:
                continue
            try:
                payload = self._get_block_run_outputs(
                    int(block_run_id),
                    sample_count=resolved_sample_count,
                )
            except ApiError:
                continue
            outputs[str(block_uuid)] = {
                "block_run_id": block_run_id,
                "status": block_run.get("status"),
                **payload,
            }
        return outputs

    def _fetch_failure_logs(
        self,
        pipeline_uuid: str,
        *,
        pipeline_run_id: int,
        include_log_content: bool,
        max_log_chars: int,
    ) -> dict[str, Any]:
        return self._fetch_pipeline_run_logs(
            pipeline_uuid,
            pipeline_run_id=pipeline_run_id,
            include_log_content=include_log_content,
            max_log_chars=max_log_chars,
        )

    def _fetch_pipeline_run_logs(
        self,
        pipeline_uuid: str,
        *,
        pipeline_run_id: int,
        include_log_content: bool,
        max_log_chars: int,
    ) -> dict[str, Any]:
        path = _query_path(
            f"/api/pipelines/{pipeline_uuid}/logs",
            {"pipeline_run_id[]": [pipeline_run_id]},
        )
        try:
            response = self.api.get(path)
        except ApiError as exc:
            return {
                "error": str(exc),
                "log_files": [],
            }

        log_entries: list[Any] = []
        if isinstance(response, dict):
            for key in ("logs", "log_files", "pipeline_logs"):
                value = response.get(key)
                if isinstance(value, list):
                    log_entries = value
                    break
            if not log_entries and isinstance(response.get("data"), list):
                log_entries = response["data"]

        log_files = []
        for entry in _flatten_pipeline_log_entries(log_entries):
            name = entry.get("name") or entry.get("filename")
            file_info = {
                "name": name,
                "path": entry.get("path") or entry.get("file"),
                "block_uuid": entry.get("block_uuid") or _block_uuid_from_log_name(name),
            }
            if include_log_content:
                content = (
                    entry.get("content")
                    or entry.get("log")
                    or entry.get("message")
                    or entry.get("error")
                )
                if isinstance(content, str) and content:
                    excerpt = _truncate_text(content, max_log_chars)
                    file_info["content"] = excerpt
                    file_info["error_excerpt"] = excerpt
            log_files.append(file_info)

        return {"log_files": log_files}
